INSERT INTO feature VALUES('imports','modules','Imports',NULL,'implemented','ordinary',NULL,'An import brings another module''s names into scope through the namespace engine: a quoted path a source''s, a module path a module''s of the package, a `path:` or `gh:` coordinate a package''s root module, and a module path headed by such a coordinate''s alias a module of that package.','surface-lowering surface-dispatcher','corpus/surface/module-import.gandr corpus/pathological/modules/import-unresolved.gandr corpus/pathological/modules/import-shadows.gandr crates/surface-dispatcher/tests/package.rs::a_module_path_through_a_coordinate_s_alias_reads_the_dependency_s_module_4715','corpus/ledger/features/imports.gandr',NULL);
